/**
 * =============================================================================
 * ORIGINATE SERVICE — OpenAPI registrations (Track 2 stage 2)
 * =============================================================================
 *
 * Second service migrated to the Track 2 generated-spec pattern. Walks the
 * primary public endpoints exposed by the originate service:
 *   - /api/documents/* (list, get, create, anchor, verify, revoke)
 *   - /api/verification/verify (canonical verifier endpoint — single source
 *     of truth across all envs after the 2026-04-29 verifier consolidation)
 *   - /api/certifications/* (issue, list, get)
 *   - /api/webhooks/* (subscribe, list, update, rotate-secret, test, deliveries)
 *   - /api/gdpr/* (consent, DSRs, exports, erasure, retention, deletion-log)
 *   - /api/system-errors/* (ingest, list, stats, resolve)
 *
 * Schemas are mirrored from frontend/shared/src/schemas/* so the generated
 * spec matches what the frontend already validates against. Until services
 * can import from a single shared schema source, keep these in lockstep
 * manually — when frontend/shared schemas change, update the matching
 * registrations here.
 *
 * Endpoints not yet registered (deferred to follow-up commits, low risk
 * because the Stage 2 deliverable was the originate proof + canonical
 * surface):
 *   - documents: /:id/sign/request, /:id/sign
 *   - verification: /verify-file, /hash, /status/:documentId
 *   - certifications: /:id/revoke, /:id/verify, /:id/share, /:id/recertify,
 *     /:id/lineage, /:id/evidence-bundle
 * =============================================================================
 */

// KS-256: FX is the canonical published-example fixture set.
// `recipientEmail` previously carried a third persona alongside auth's
// two; drawing from FX collapses them onto one counterparty.
import { z, sharedRegistry, commonErrorResponses, rateLimit, sla, FX } from '@secuura/shared';
import { LIFECYCLE_EVENT_ACTIONS } from './lifecycleActions';
// QA F-8: the sentinel is INTERPOLATED into the published descriptions rather
// than hand-written, so the value a relying party reads in the spec cannot
// drift from the value the erasure actually writes. This file is TypeScript;
// there is no reason for it to carry a copy of the literal.
import { ERASED_MARKER } from './utils/erasureMarker';

// -----------------------------------------------------------------------------
// SHARED SCHEMAS (registered once, referenced by routes)
// -----------------------------------------------------------------------------

// KS-367: charset-safety constraint for id-style path parameters. Every id the
// platform mints (doc-<ts>-<8hex>, ce_<uuid>, plain UUIDs, webhook ids) fits
// this pattern; what it EXCLUDES is NUL/control bytes and other unsafe
// characters, which gateways (local nginx, ACA Envoy) reject with their own
// undocumented 400 before the request reaches a service. Constraining the
// spec makes such values schema-invalid input rather than a documented-
// response violation. Charset safety only — NOT an entity id format.
// Exported for runtime enforcement (KS-466 §8: routes/documents.ts rejects
// charset-illegal path ids before any DB query — the published grammar and
// the runtime guard must stay one definition).
export const SAFE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

// Reusable `{id}` path-params objects carrying the safe-charset constraint.
//
// KS-665 item 2: these were ONE shared `idPathParams` used by 18 routes across
// three different resource types. That is fine for the constraint (the grammar
// is the same) but it makes a published example impossible: a single `example:`
// here would document a document id on `/api/webhooks/{id}`. That is the same
// defect class as the 16 `address` fields in §3 and the `userAgent` in §4 — a
// legitimate fixture value landing on a field it does not describe — so the
// helper is split by resource and each carries its own example.
//
// The examples below are FORMAT-TRUE AND ACCOUNT-FALSE by design: FX names no
// live row (see the fixture-set header). A path-param example documents the
// SHAPE a caller must send, not an id they can fetch.
const idPathParamsBase = (description: string) =>
  z.string().regex(SAFE_ID_PATTERN).openapi({ description });

const documentIdPathParams = z.object({
  id: idPathParamsBase(
    'Document id (1-128 chars: alphanumeric plus `.`, `_`, `-`; must start alphanumeric)',
  ).openapi({ example: FX.document.id }),
});

const certificationIdPathParams = z.object({
  id: idPathParamsBase(
    'Certification id (1-128 chars: alphanumeric plus `.`, `_`, `-`; must start alphanumeric)',
  ).openapi({ example: FX.certification.id }),
});

// No example deliberately: FX carries no webhook-shaped id, and the fixture
// rule is that published literals come only from curated FX or from schema
// synthesis. Adding one means a new FX entry AND the matching accept-list
// entry in scripts/spec-examples/check/contract.mjs — out of scope here.
// See the KS-665 comment for the 90 parameters in the same position.
const webhookIdPathParams = z.object({
  id: idPathParamsBase(
    'Webhook id (1-128 chars: alphanumeric plus `.`, `_`, `-`; must start alphanumeric)',
  ),
});

// Document list item — mirrors frontend/shared/src/schemas/documents.ts.
// passthrough() because the originate service projects DocumentRecord
// fields permissively; structural id/status are load-bearing.
const DocumentListItemSchema = sharedRegistry.register(
  'DocumentListItem',
  z
    .object({
      id: z.string(),
      title: z.string().openapi({
        description:
          `The document title. The exact string '${ERASED_MARKER}' is a SENTINEL, not a `
          + 'filename: it means the title was removed under a GDPR Art. 17 erasure. '
          + 'The column is NOT NULL, so an erased title holds this marker rather '
          + 'than null. Treat it as "no title available", never as content.',
      }),
      documentType: z.string().optional().nullable().openapi({
        description:
          `Caller-supplied classification. The exact string '${ERASED_MARKER}' is the same `
          + 'GDPR Art. 17 sentinel as on `title` (QA F-2): the column is free text that '
          + 'nothing sanitises, so it is erased with the subject. The column is NOT NULL, '
          + 'so an erased row holds the marker rather than null. An erased document will '
          + 'therefore not match any real type filter — that is intended.',
      }),
      status: z.string(),
      contentHash: z.string().optional().nullable(),
      createdAt: z.string(),
      updatedAt: z.string(),
    })
    .passthrough()
    .openapi({
               // KS-256: generated example (synthesised, masked). Guarded by
               // `npm run check:openapi` -> check-spec-examples (E1-E7).
               example: {
                 id: 'example-id',
                 title: 'example-title',
                 status: 'example-status',
                 createdAt: 'example-createdAt',
                 updatedAt: 'example-updatedAt',
               },
      description: 'A document as returned in list views (projected from DocumentRecord).',
    }),
);

const DocumentListResponseSchema = sharedRegistry.register(
  'DocumentListResponse',
  z.object({
    documents: z.array(DocumentListItemSchema),
    total: z.number().int().nonnegative(),
    page: z.number().int().positive(),
    limit: z.number().int().positive(),
  }).openapi({
  // KS-256: generated example (synthesised, masked). Guarded by
  // `npm run check:openapi` -> check-spec-examples (E1-E7).
    example: {
    documents: [
      {
        id: 'example-id',
        title: 'example-title',
        status: 'example-status',
        createdAt: FX.timestamps.createdAt,
        updatedAt: FX.timestamps.createdAt,
      },
      {
        id: 'example-id',
        title: 'example-title',
        status: 'example-status',
        createdAt: FX.timestamps.createdAt,
        updatedAt: FX.timestamps.createdAt,
      },
    ],
    total: 0,
    page: 1,
    limit: 1,
  },
  }),
);

const DocumentDetailSchema = sharedRegistry.register(
  'DocumentDetail',
  z
    .object({
      id: z.string(),
      // KS-596 Phase B: canonical UUID alongside the legacy id on reads.
      documentUuid: z.string().uuid().nullable().optional(),
      type: z.string().optional(),
      status: z.string(),
      contentHash: z.string().optional().nullable(),
      createdAt: z.string(),
      updatedAt: z.string(),
      owner: z
        .object({
          id: z.string().optional(),
          name: z.string().optional().nullable(),
        })
        .passthrough()
        .optional()
        .nullable(),
      data: z.record(z.string(), z.unknown()).optional().nullable(),
      // KS-480 §6: creation attribution echo (first-class provenance).
      // Present only on connector-created documents that carried onBehalfOf;
      // pseudonymised rows (post-erasure) echo externalRef with null
      // email/displayName and pseudonymised=true.
      createdOnBehalfOf: z
        .object({
          email: z.string().nullable(),
          displayName: z.string().nullable(),
          externalRef: z.string().nullable(),
          resolvedUserId: z.string().nullable(),
          pseudonymised: z.boolean(),
        })
        .optional(),
    })
    .passthrough()
    .openapi({
      description: 'Full document including provenance + nested data.',
      example: {
        id: 'doc-0000000000000-5eeded0c',
        type: 'PROPERTY_DEED',
        status: 'CERTIFIED',
        contentHash: 'a1b2c3d4e5f60718293a4b5c6d7e8f901a2b3c4d5e6f70819203a4b5c6d7e8f9',
        createdAt: '2026-04-29T10:14:21.120Z',
        updatedAt: '2026-04-29T10:14:23.481Z',
        owner: {
          // KS-256: was `user_01HC9ZK1ABCDEFGHIJKL`. `verify-spec-examples`
          // observed 7 of 7 real `data.user.id` values to be UUIDs, so the
          // ULID-ish form published a format the API never emits. FX.issuer.id
          // is UUID-shaped and backs no account. Guard rule E8 catches this now.
          id: FX.issuer.id,
          name: FX.issuer.displayName,
        },
        data: {
          propertyAddress: '42 Plinth Lane, London EC1A 1BB, UK',
          titleNumber: 'TGL123456',
          recipientEmail: FX.holder.email,
        },
      },
    }),
);

// KS-480 §6: connector-only attribution of the real Platform-S user behind an
// sk_-key call. JWT callers sending it get 400; a cross-org email gets 403.
// Stored encrypted off-chain (action_provenance), NEVER anchored on-chain.
const OnBehalfOfSchema = sharedRegistry.register(
  'OnBehalfOf',
  z
    .object({
      email: z.string().trim().min(3).max(255).email(),
      displayName: z.string().trim().min(1).max(255).optional(),
      externalRef: z.string().trim().min(1).max(128).optional().openapi({
        description: "The caller's stable user id (Platform S PersonGuid) — survives GDPR pseudonymisation as the attribution id.",
      }),
    })
    .openapi({
               // KS-256: generated example (synthesised, masked). Guarded by
               // `npm run check:openapi` -> check-spec-examples (E1-E7).
               example: {
                 email: FX.issuer.email,
               },
      description:
        'Connector-only (sk_ key) attribution of the real user the connector acts for. ' +
        'Interactive (JWT) callers must not send it (400). Resolved tenant-scoped against ' +
        "the key's own Organisation: same-org K user → per-user attribution; different " +
        'org → 403; no K user → stored verbatim as provenance. Never creates an account, ' +
        'never grants auth, never anchored on-chain.',
    }),
);

const DocumentCreateRequestSchema = sharedRegistry.register(
  'DocumentCreateRequest',
  z
    .object({
      title: z.string(),
      documentType: z.string().optional(),
      data: z.record(z.string(), z.unknown()).optional(),
      onBehalfOf: OnBehalfOfSchema.optional(),
      // KS-596 (architecture P1, Phase A): optional S-supplied identifiers.
      // KS-663 divergence 2: the runtime guard (documents.ts UUID_V4_RE) rejects
      // any non-v4 documentUuid with 400, but the generated spec published a bare
      // `format: uuid`, which every RFC 4122 version satisfies — so a v7 UUID
      // passed spec validation and 400'd at runtime. `.uuid()` keeps `format:
      // uuid`; the explicit `pattern` publishes the v4 constraint the code
      // actually enforces. Case-insensitive `[0-9a-fA-F]` because the runtime
      // regex uses the /i flag and JSON Schema `pattern` has no flag.
      // (userUuid / organizationUuid keep bare `format: uuid` on purpose — the
      // runtime accepts any RFC 4122 version for those; only documentUuid is v4.)
      documentUuid: z.string().uuid().optional().openapi({
        pattern: '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$',
        description:
          'Optional caller-supplied registration UUID (v4). Becomes the '
          + "document's canonical identifier (stored as external_id, which is "
          + 'UNIQUE). Re-POSTing a seen documentUuid with the SAME contentHash '
          + 'returns 200 with the existing registration (idempotent retry); '
          + 'the same documentUuid with DIFFERENT content is 409. When absent, '
          + 'K mints its legacy id exactly as before.',
      }),
      userUuid: z.string().uuid().optional().openapi({
        description:
          'Optional caller-supplied acting-user UUID (Platform S resolves it '
          + 'at login). Accepted and preserved with the registration; not yet '
          + 'an authorization input.',
      }),
      organizationUuid: z.string().uuid().optional().openapi({
        description:
          'Optional organization UUID the registration is attributed to. It is '
          + 'BOUND TO THE ACTING ORGANISATION and must identify it by one of its two '
          + 'identifiers: its Platform K organization id, or the `externalRef` it was '
          + 'registered with through register-connector (so a Platform S connector may '
          + 'send its own Organisation GUID). A value that DIFFERS FROM both is refused '
          + 'with 403 — it is not silently ignored. The test is identity with the acting '
          + 'Organisation, not membership: a well-formed UUID belonging to another '
          + 'Organisation, or to no Organisation at all, is refused too. Either accepted '
          + 'form is attributed to the acting Organisation by its Platform K id. '
          + 'A caller with no Organisation of its own is not refused, but its '
          + 'value cannot be bound and so is not attributed (the column is left '
          + 'empty; the value you sent is still preserved in the registration '
          + 'metadata). Omitting the field is unchanged and remains valid — this '
          + 'is a refusal, not a new requirement. To attribute on behalf of '
          + 'another party, use `onBehalfOf`, not this field.',
      }),
    })
    .openapi({
      example: {
        title: 'Property Deed — 42 Plinth Lane',
        documentType: 'PROPERTY_DEED',
        data: {
          propertyAddress: '42 Plinth Lane, London EC1A 1BB, UK',
          titleNumber: 'TGL123456',
          recipientEmail: FX.holder.email,
        },
      },
    }),
);

// KS-440: POST /api/documents returns a FLAT body, not a `{ document: … }`
// wrapper. This flat shape is the Platform-S contract — S's
// CardanoAnchorService.cs reads `{ id, status, contentHash }` off the top
// level (confirmed) — so the published response documents exactly what the
// handler emits (routes/documents.ts `res.status(201).json({ id, type,
// status, contentHash, txHash, createdAt, requiresWalletSignature })`).
// `txHash` is always present but null until anchoring confirms (the handler's
// F-DOC-RESP-SHAPE-01 note); `.passthrough()` keeps it forward-compatible.
const DocumentCreateResponseSchema = sharedRegistry.register(
  'DocumentCreateResponse',
  z
    .object({
      id: z.string(),
      // KS-596 Phase B: canonical UUID for the registration — the caller's
      // documentUuid when one was supplied, else the row's own UUID key.
      // Both resolve via GET /api/documents/{id}.
      documentUuid: z.string().uuid(),
      type: z.string(),
      status: z.string(),
      contentHash: z.string(),
      txHash: z.string().nullable(),
      createdAt: z.string(),
      requiresWalletSignature: z.boolean(),
    })
    .passthrough().openapi({
  // KS-256: generated example (synthesised, masked). Guarded by
  // `npm run check:openapi` -> check-spec-examples (E1-E7).
    example: {
    id: FX.document.id,
    // KS-596 Phase B made documentUuid required on this schema; the KS-256
    // example was written before that and omitted it, which failed tsc in the
    // originate image after the develop merge. See FX.document.uuid.
    documentUuid: FX.document.uuid,
    type: 'example-type',
    status: 'example-status',
    contentHash: FX.document.contentHash,
    txHash: null,
    createdAt: FX.timestamps.createdAt,
    requiresWalletSignature: true,
  },
  }),
);

// Verify shapes — mirrors frontend/shared/src/schemas/verify.ts.
// `partial()` on checks supports BOTH the originate (production) shape AND
// the legacy api-gateway-mock shape, so older clients (Gmail addon, third-
// party verifier scripts) keep parsing cleanly during the cutover.
const VerifyChecksSchema = sharedRegistry.register(
  'VerifyChecks',
  z
    .object({
      // Originate (production) shape:
      documentExists: z.boolean(),
      hashValid: z.boolean(),
      // KS-563: `isCertified` means an issuer CERTIFIED this document
      // (`status === 'certified'`) — nothing else. It was previously true for
      // merely-anchored and signed documents too, so upload-only documents
      // reported a certification nobody performed.
      isCertified: z.boolean().openapi({
        description:
          'True only when an issuer certified this document. A document that '
          + 'was merely originated and anchored is NOT certified — read '
          + '`isAnchored` for chain presence and `certification` for the '
          + 'certification act itself. KS-584: the evidence is read from the '
          + 'whole same-hash registration set (the certify flow records the '
          + 'act on a derived row), not only the selected row’s status.',
      }),
      // KS-563: chain presence, distinct from certification. KS-522 rules
      // apply — a simulated anchor (tx_sim_/mock_tx_) is never `isAnchored`.
      isAnchored: z.boolean().openapi({
        description:
          'True when the document has a real on-chain anchor. Simulated anchors '
          + '(`simulated: true`) never set this.',
      }),
      isRevoked: z.boolean(),
      integrityVerified: z.boolean().openapi({
        description:
          'Hash matched, document is registry-valid (certified, anchored or signed) '
          + 'and not revoked. Deliberately BROADER than `isCertified` — it does not '
          + 'assert that anyone certified the document.',
      }),
      // Legacy / api-gateway-mock shape:
      exists: z.boolean(),
      notRevoked: z.boolean(),
      hasSignatures: z.boolean(),
      blockchainAnchored: z.boolean(),
    })
    .partial().openapi({
  // KS-256: generated example (synthesised, masked). Guarded by
  // `npm run check:openapi` -> check-spec-examples (E1-E7).
    example: {
    documentExists: true,
    hashValid: true,
    isCertified: true,
    isRevoked: true,
    integrityVerified: true,
    exists: true,
    notRevoked: true,
    hasSignatures: true,
    blockchainAnchored: true,
  },
  }),
);

// KS-563: the certification act, distinct from anchoring. Emitted ONLY when an
// issuer certified the document, so consumers can test presence rather than
// inferring certification from a status or an anchor.
const VerifyCertificationSchema = sharedRegistry.register(
  'VerifyCertification',
  z
    .object({
      certificationId: z.string().nullable().openapi({ description: 'Id of the certification that certified this document.' }),
      certificationType: z.string().nullable().openapi({ description: 'Certification type recorded at issue time.' }),
      certifiedAt: z.string().nullable().openapi({ description: 'UTC ISO-8601 timestamp of the certification act.' }),
      certifiedBy: z.string().nullable().openapi({ description: 'Display name of the certifying issuer.' }),
      certifierOrganizationId: z.string().nullable().openapi({ description: 'Organisation id of the certifying issuer.' }),
    })
    .passthrough()
    .openapi({
      description:
        'The certification act. Present ONLY when an issuer certified the document — '
        + 'its absence means no certification happened (KS-563). Fields may be null '
        + 'for certifications issued before a given field was recorded.',
    }),
);

const VerifyResponseSchema = sharedRegistry.register(
  'VerifyResponse',
  z
    .object({
      verified: z.boolean(),
      documentId: z.string().optional(),
      certificationId: z.string().optional(),
      status: z.string().optional(),
      revoked: z.boolean().optional(),
      hash: z.string().optional(),
      matchedBy: z.string().optional(),
      strategy: z.string().optional(),
      source: z.string().optional(),
      reason: z.string().optional(),
      error: z.string().optional(),
      code: z.string().optional(),
      verifiedAt: z.string().optional(),
      verificationConfidence: z.string().optional(),
      checks: VerifyChecksSchema.optional(),
      onChainMetadata: z.unknown().optional(),
      requestedFields: z.array(z.string()).optional(),
      purpose: z.string().optional(),
      // KS-522: honest labelling of simulated anchors. When present and true,
      // the document's anchor is a simulation (tx_sim_/mock_tx_ placeholder —
      // NO Cardano transaction exists): `blockchain.txHash` is null, the
      // placeholder moves to `blockchain.simulatedTxRef`, and no relying party
      // should treat the result as on-chain proof.
      simulated: z.boolean().optional(),
      // KS-563: the certification act. PRESENT only when an issuer actually
      // certified the document; its ABSENCE is the honest signal that no
      // certification happened (a merely-anchored document has no such object).
      certification: VerifyCertificationSchema.optional(),
    })
    .passthrough()
    .openapi({
      description:
        'Verification envelope. Load-bearing field is `verified`; everything else is ' +
        'rendered when present. Originate is the single source of truth across all ' +
        'envs after the 2026-04-29 verifier consolidation. Note `verified` means ' +
        '"registry-valid, hash intact, not revoked" — it does NOT mean certified; ' +
        'read `checks.isCertified` / `certification` for that (KS-563).',
      example: {
        verified: true,
        documentId: 'doc-0000000000000-5eeded0c',
        status: 'CERTIFIED',
        revoked: false,
        hash: 'a1b2c3d4e5f60718293a4b5c6d7e8f901a2b3c4d5e6f70819203a4b5c6d7e8f9',
        matchedBy: 'documentId',
        strategy: 'chain-first',
        source: 'cardano-preprod',
        verifiedAt: '2026-04-29T10:20:00.000Z',
        verificationConfidence: 'high',
        checks: {
          documentExists: true,
          hashValid: true,
          isCertified: true,
          isAnchored: true,
          isRevoked: false,
          integrityVerified: true,
        },
        // KS-256: ids drawn from FX, not written inline. The literals here
        // before were a hand-written cert id and a random UUID, which guard
        // rule E8 fails — an off-fixture identifier may name a live account.
        certification: {
          certificationId: FX.certification.id,
          certificationType: FX.certification.type,
          certifiedAt: '2026-04-29T10:19:00.000Z',
          certifiedBy: 'Oxford University',
          certifierOrganizationId: FX.certification.organizationId,
        },
      },
    }),
);

const VerifyRequestSchema = sharedRegistry.register(
  'VerifyRequest',
  z
    .object({
      documentId: z.string().optional(),
      hash: z.string().optional(),
      title: z.string().optional(),
      contentHash: z.string().optional(),
    })
    .passthrough()
    .openapi({
               // KS-256: generated example (synthesised, masked). Guarded by
               // `npm run check:openapi` -> check-spec-examples (E1-E7).
               example: {
                 documentId: FX.document.id,
                 hash: 'example-hash',
                 title: 'example-title',
                 contentHash: '<contentHash>',
               },
      description:
        'Verification request. Provide ONE OR MORE of documentId, hash, title, contentHash. ' +
        'The verifier tries chain-first, then originate-id lookup, then hash/title strategies.',
    }),
);

// -----------------------------------------------------------------------------
// KS-584 P3 — the /v2 verify-list contract
// -----------------------------------------------------------------------------
// v1 collapses the same-hash registration set to ONE row; v2 returns every
// registration as its own match, each standing on its own evidence. Anchor
// truth is caller-independent: the anchoring chain-fact read is pre-auth and
// no caller bearer is forwarded, so anonymous and authenticated callers get
// identical anchor facts.

const V2VerifyRequestSchema = sharedRegistry.register(
  'V2VerifyRequest',
  z
    .object({
      hash: z.string().optional().openapi({ description: 'SHA-256 content hash, with or without the sha256: prefix.' }),
      contentHash: z.string().optional().openapi({ description: 'Alias of hash.' }),
      providedHash: z.string().optional().openapi({ description: 'Alias of hash.' }),
      documentHash: z.string().optional().openapi({ description: 'Alias of hash.' }),
      documentId: z.string().optional().openapi({
        description:
          'Registration identifier — the S-supplied documentUuid (KS-596) or the platform '
          + 'document id. Used only when no hash is supplied; answers existence, not integrity.',
      }),
      documentData: z.record(z.string(), z.unknown()).optional().openapi({
        description: 'Raw JSON document content to hash server-side when no hash is supplied.',
      }),
    })
    .passthrough()
    .openapi({
      description:
        'v2 verification request. Provide a content hash (strongest — proves integrity), '
        + 'documentData to hash server-side, or a documentId (existence only).',
    }),
);

const V2VerifyMatchSchema = sharedRegistry.register(
  'V2VerifyMatch',
  z
    .object({
