const CertificationIssueRequestSchema = sharedRegistry.register(
  'CertificationIssueRequest',
  z
    .object({
      // KS-430: the runtime validator (routes/certifications.ts) requires
      // `type` (this enum) and `data` (an object) — the certification's core
      // payload — and treats `documentId` as OPTIONAL (used only by the
      // pre-lineage certify path). The published schema had drifted to require
      // `documentId` and omit `type`/`data`, so a spec-minimal `{documentId}`
      // body earned a 400. Declare the real contract: `type`/`data` required,
      // `documentId` optional. Enum mirrors the runtime's allowed list so a
      // spec-valid `type` is a runtime-valid `type` (not a stricter narrowing
      // of an existing spec field — the field was previously absent).
      type: z
        .enum([
          'educational_degree',
          'employment_certificate',
          'professional_certification',
          'employment_reference',
          'identity_document',
          'certificate',
          'verification_certificate',
          'signed_document',
          'DOCUMENT',
        ])
        .openapi({ description: 'Certification type. Required by the certify route.' }),
      data: z.record(z.string(), z.unknown()).openapi({
        description:
          'Certification payload object (required). Free-form issuer data. ' +
          'KS-475 (§4): values must be storable — payloads Postgres cannot ' +
          'persist (e.g. NUL escape sequences, over-length or uncastable ' +
          'values) answer 400 BAD_REQUEST "Certification payload contains ' +
          'values that cannot be stored". The rule is a storage boundary, ' +
          'not a fixed field constraint, so it cannot be expressed as a ' +
          'schema pattern. KS-543: this object is CONTENT-HASHED into the ' +
          'certification (immutable once issued), so do not place personal ' +
          'data in it — the reserved identity keys `actorName`, `actorEmail` ' +
          'and `onBehalfOf` are silently STRIPPED before hashing (use the ' +
          'top-level onBehalfOf field for attribution instead).',
      }),
      documentId: z.string().optional(),
      metadata: z.record(z.string(), z.unknown()).optional(),
      onBehalfOf: OnBehalfOfSchema.optional(),
      // KS-70: optional lifecycle parent. When set, the certify route
      // creates a NEW document linked via parent_document_id (a child
      // node in the lifecycle chain) and rejects with 422 LINEAGE_CYCLE
      // if the proposed ancestor chain would loop. See SCOPES.md and the
      // verify endpoint's lineage response for how this is surfaced.
      parentDocumentId: z.string().optional().openapi({
        description:
          'External id of the predecessor document. When set, the issued ' +
          'certification produces a new linked document (same external_id ' +
          'as the certification) with `parent_document_id` pointing at this. ' +
          'Cycles are rejected with 422 LINEAGE_CYCLE before any anchor or ' +
          'write happens. Walk capped at MAX_LINEAGE_DEPTH (default 12).',
      }),
    })
    .passthrough().openapi({
  // KS-256: generated example (synthesised, masked). Guarded by
  // `npm run check:openapi` -> check-spec-examples (E1-E7).
    example: {
    type: 'educational_degree',
    data: {},
  },
  }),
);

