    // KS-267: mirror the handler's SystemErrorsQuerySchema (routes/systemErrors.ts)
    // — severity is the SystemError union, limit/offset are bounded integers — so
    // schemathesis's negative_data_rejection probes hit declared, validated params.
    query: z.object({
      service: z.string().min(1).optional(),
      severity: z.enum(['warning', 'error', 'critical']).optional(),
      resolved: z.enum(['true', 'false']).optional(),
      limit: z.coerce.number().int().positive().max(500).optional(),
      // KS-423: .openapi({type:'integer'}) pins the emitted type — zod-to-openapi
      // renders coerce+min(0) as `type: [integer, "null"]`, admitting a null the
      // handler correctly 400s (positive_data_acceptance false-accept).
      offset: z.coerce.number().int().min(0).optional().openapi({ type: 'integer', minimum: 0 }),
    }),
  },
  responses: {
    400: commonErrorResponses[400],
